INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem Binär-Stream?', 2, '[{"text": "Datenfluss in Binärform", "correct": true, "because": "Reihe von Bits"}, {"text": "Grafische Datenanzeige", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Binär-Stream?', 3, '[{"text": "Effiziente Datenübertragung", "correct": true, "because": "Rohdaten verarbeiten"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen nutzen Binär-Streams?', 5, '[{"text": "Dateioperationen", "correct": true, "because": "Binäre Dateien lesen/schreiben"}, {"text": "Netzwerkkommunikation", "correct": true, "because": "Datenpakete"}, {"text": "Textformatierung", "correct": false, "because": "Text-Streams"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Binär-Stream besteht aus 0 und 1. b) Er ist nur für Textdaten geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für alle Daten, nicht nur Text"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Binär-Stream?', 4, '[{"text": "Datenformat", "correct": false, "because": "Wichtig für Verarbeitung"}, {"text": "Byte-Reihenfolge", "correct": false, "because": "Endianness entscheidend"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Binär-Stream für Dateien genutzt wird?', 2, '[{"text": "Ja", "correct": true, "because": "Binäre Dateizugriffe"}, {"text": "Nein", "correct": false, "because": "Häufig verwendet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Programmiersprache nutzt Binär-Streams für Dateien?', 3, '[{"text": "Java", "correct": true, "because": "InputStream/OutputStream"}, {"text": "HTML", "correct": false, "because": "Keine Programmiersprache"}, {"text": "CSS", "correct": false, "because": "Kein Dateizugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Verarbeitung eines Binär-Streams?', 5, '[{"text": "Lesen von Bytes", "correct": true, "because": "Binäre Daten"}, {"text": "Schreiben von Bits", "correct": true, "because": "Datenfluss"}, {"text": "Textformatierung", "correct": false, "because": "Text-Streams"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Binär-Streams sind für Rohdaten geeignet. b) Sie sind langsamer als Text-Streams. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft schneller"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Binär-Stream unwichtig?', 4, '[{"text": "Byte-Reihenfolge", "correct": false, "because": "Endianness wichtig"}, {"text": "Datenintegrität", "correct": false, "because": "Fehler vermeiden"}, {"text": "Farbe der Daten", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Binär-Stream verschlüsselt sein?', 2, '[{"text": "Nein", "correct": true, "because": "Optional"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Binär-Stream?', 4, '[{"text": "Effiziente Verarbeitung", "correct": true, "because": "Rohdaten direkt"}, {"text": "Kompakte Speicherung", "correct": true, "because": "Keine Konvertierung"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Binär-Streams nur für große Dateien sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Dateien"}, {"text": "Ja", "correct": false, "because": "Universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Binär-Stream?', 3, '[{"text": "Datenintegrität", "correct": true, "because": "Fehlerfreiheit"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Binär-Streams nutzen Bytes. b) Sie sind nur für Netzwerkdaten nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Dateien"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein schlecht gehandhabter Binär-Stream?', 5, '[{"text": "Datenverlust", "correct": true, "because": "Fehler bei Verarbeitung"}, {"text": "Inkompatibilität", "correct": true, "because": "Falsche Endianness"}, {"text": "Schnellere Übertragung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei Binär-Streams?', 3, '[{"text": "Datenverarbeitung implementieren", "correct": true, "because": "Programmierung"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Binär-Stream komprimiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. ZIP"}, {"text": "Nein", "correct": false, "because": "Möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für Binär-Streams nutzen?', 4, '[{"text": "Wireshark", "correct": true, "because": "Netzwerkanalyse"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
